def check_local_coloring(N=4):
    """
    Checks if 4 colors are sufficient for the local constraint (King's graph coloring)
    on an N x N grid using the pattern based on (i mod 2, j mod 2).
    """

    # Map (i mod 2, j mod 2) to 4 unique color indices (0 to 3)
    def get_color(r, c):
        return (r % 2) * 2 + (c % 2)

    N_colors = 4

    # Store the colors assigned to the grid
    colors = {}
    for r in range(N):
        for c in range(N):
            colors[(r, c)] = get_color(r, c)

    # Iterate over all points and check their neighbors
    violations = []
    for r in range(N):
        for c in range(N):
            current_color = colors[(r, c)]

            # Check all 8 neighbors (a, b) where a, b in {r-1, r, r+1} and not (r, c)
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue

                    nr, nc = r + dr, c + dc

                    # Check if the neighbor is within the domain
                    if 0 <= nr < N and 0 <= nc < N:
                        neighbor_color = colors[(nr, nc)]

                        # Local constraint: neighboring points must have different colors
                        if current_color == neighbor_color:
                            violations.append(((r, c), (nr, nc), current_color))

    if not violations:
        print(f"Success: 4 colors are sufficient for a {N}x{N} domain.")
        print("The local minimum number of colors required is 4.")
    else:
        print(f"Failure: Found {len(violations)} violations.")
        print("Example violation: {violations[0]}")

